"""Offline build-tool checks; generated bytes below are control fixtures only."""
import contextlib
import hashlib
import importlib.util
import io
import json
from pathlib import Path
import struct
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[2]
SCRIPT = ROOT / "scripts/build_t27_streaming.py"
spec = importlib.util.spec_from_file_location("build_t27_streaming", SCRIPT)
build = importlib.util.module_from_spec(spec)
spec.loader.exec_module(build)
BASELINE = ROOT.parent / "context/PRODUCTION_COMPILE.json"


class ProductionBuildTests(unittest.TestCase):
    def setUp(self):
        self.receipt = json.loads(BASELINE.read_text())

    def test_command_preserves_parent_contract_and_adds_real_stream(self):
        source = Path("/tmp/t27 source candidate")
        output = Path("/tmp/t27 build candidate")
        argv = build.rewrite_command(self.receipt, source, output, "/tool/bin/riscv32-unknown-elf-gcc")
        stream = str(source / "firmware/runtime/port/stream.c")
        self.assertEqual(argv.count(stream), 1)
        self.assertIn(str(source / "firmware/runtime/board/main.c"), argv)
        self.assertIn(str(output / "tokenizer.S"), argv)
        self.assertEqual(argv[argv.index("-o") + 1], str(output / "application.elf"))
        old_root = next(x for x in self.receipt["argv"] if x.endswith("/firmware/runtime/board/main.c")).removesuffix("/firmware/runtime/board/main.c")
        old_generated = str(Path(next(x for x in self.receipt["argv"] if x.endswith("/tokenizer.S"))).parent)
        normalized = [self.receipt["argv"][0]]
        for arg in argv[1:]:
            if arg == stream or arg.startswith("-ffile-prefix-map="):
                continue
            normalized.append(arg.replace(str(source), old_root).replace(str(output), old_generated))
        expected = [x for x in self.receipt["argv"] if not x.startswith("-ffile-prefix-map=")]
        self.assertEqual(normalized, expected)
        self.assertFalse(any("/home/Jiang/" in x for x in argv))

    def test_enhancement_build_declares_sources_and_bound_identity(self):
        output = Path('/tmp/identity-build')
        baseline = build.rewrite_command(self.receipt, ROOT, output, 'rv32-gcc')
        enhanced = build.rewrite_command(self.receipt, ROOT, output, 'rv32-gcc', enhancements=True)
        for flag in ('-DNX_T27_SERVICE_ENHANCEMENTS=1', '-DNX_PROFILE_INTEGER=1', '-DNX_PREFIX_CAPTURE=1'):
            self.assertIn(flag, enhanced); self.assertNotIn(flag, baseline)
        for name in ('prefix.c', 'control.c'):
            self.assertEqual(sum(x.endswith('/' + name) for x in enhanced), 1)
        first, header = build.runtime_identity(ROOT, enhanced, 'compiler-a')
        second, _ = build.runtime_identity(ROOT, enhanced, 'compiler-b')
        self.assertEqual(len(first), 3)
        self.assertNotEqual(first['T27_NUMERIC_SHA256'], second['T27_NUMERIC_SHA256'])
        for name, digest in first.items():
            self.assertEqual(len(digest), 64); self.assertIn(digest, header)

    def test_wrong_parent_or_old_object_is_rejected(self):
        for change in (lambda a: a.remove("-fno-fast-math"), lambda a: a.append("/old/model.o")):
            receipt = dict(self.receipt, argv=list(self.receipt["argv"]))
            change(receipt["argv"])
            with self.assertRaises(ValueError):
                build.rewrite_command(receipt, ROOT, Path("/tmp/new-build"), "gcc")

    def test_all_enhancements_are_explicit_and_bound_to_identity(self):
        with tempfile.TemporaryDirectory() as temp:
            capture = io.StringIO()
            with contextlib.redirect_stdout(capture):
                result = build.main(["--generated", temp, "--output", str(Path(temp) / "planned"),
                                     "--cc", "/no/such/gcc", "--all-enhancements", "--dry-run"])
            self.assertEqual(result, 0)
            plan = json.loads(capture.getvalue())
            self.assertEqual(plan['features'], dict.fromkeys(('service_enhancements','kv_tail_direct','pv_long','head_argmax'), True))
            for macro in ('NX_T27_SERVICE_ENHANCEMENTS','NX_PROFILE_INTEGER','NX_PREFIX_CAPTURE',
                          'NX_KV_TAIL_DIRECT','NX_PV_LONG','NX_HEAD_ARGMAX'):
                self.assertEqual(plan['argv'].count('-D' + macro + '=1'), 1)
            self.assertEqual(len(plan['runtime_identities']), 3)
            self.assertFalse((Path(temp) / "planned").exists())
        simple = build.rewrite_command(self.receipt, ROOT, Path('/tmp/optional'), 'gcc', enhancements=True)
        extended = build.rewrite_command(self.receipt, ROOT, Path('/tmp/optional'), 'gcc', enhancements=True, kv_tail_direct=True)
        self.assertNotEqual(build.runtime_identity(ROOT, simple, 'test')[0]['T27_NUMERIC_SHA256'],
                            build.runtime_identity(ROOT, extended, 'test')[0]['T27_NUMERIC_SHA256'])
        for override in ('-DNX_KV_TAIL_DIRECT=0', '-DNX_PROFILE_INTEGER', '-UNX_HEAD_ARGMAX'):
            with self.subTest(override=override), self.assertRaises(ValueError):
                build.rewrite_command(dict(self.receipt, argv=self.receipt['argv'] + [override]),
                                      ROOT, Path('/tmp/optional'), 'gcc', kv_tail_direct=True)

    def test_optimized_command_changes_only_uniform_optimization_flag(self):
        source, output = Path("/tmp/t27 source candidate"), Path("/tmp/t27 build candidate")
        baseline = build.rewrite_command(self.receipt, source, output, "rv32-gcc", "baseline")
        optimized = build.rewrite_command(self.receipt, source, output, "rv32-gcc", "optimized")
        self.assertEqual(optimized, ["-O3" if arg == "-O2" else arg for arg in baseline])
        self.assertEqual([arg for arg in optimized if arg.startswith("-O")], ["-O3"])
        self.assertIn("-ffp-contract=off", optimized)
        self.assertIn("-fno-fast-math", optimized)
        self.assertFalse(any(arg.startswith("-flto") for arg in optimized))

    def test_conflicting_arithmetic_isa_and_backend_flags_are_rejected(self):
        overrides = ("-ffp-contract=fast", "-ffast-math", "-fassociative-math",
                     "-freciprocal-math", "-ffinite-math-only", "-fno-signed-zeros",
                     "-march=rv32imafdc", "-mabi=ilp32", "-DNX_PV_SHARED=0",
                     "-DT27_M4_HANDOFF=0", "-DNX_OPT07_DEFAULT=1")
        for override in overrides:
            with self.subTest(override=override):
                receipt = dict(self.receipt, argv=self.receipt["argv"] + [override])
                with self.assertRaises(ValueError):
                    build.rewrite_command(receipt, ROOT, Path("/tmp/new-build"), "gcc", "optimized")

    def test_inherited_optimization_and_lto_cannot_override_selected_profile(self):
        for flag in ("-O0", "-O2", "-O3", "-Ofast", "-Os", "-flto", "-flto=auto", "-fwhole-program"):
            with self.subTest(flag=flag):
                receipt = dict(self.receipt, argv=self.receipt["argv"] + [flag])
                with self.assertRaises(ValueError):
                    build.rewrite_command(receipt, ROOT, Path("/tmp/new-build"), "gcc", "optimized")

    def test_unknown_profile_rejected_before_output_creation(self):
        with self.assertRaises(ValueError):
            build.rewrite_command(self.receipt, ROOT, Path("/tmp/new-build"), "gcc", "fast-math")
        with tempfile.TemporaryDirectory() as temp:
            output = Path(temp) / "no-build"
            with contextlib.redirect_stderr(io.StringIO()), self.assertRaises(SystemExit) as error:
                build.main(["--generated", temp, "--output", str(output), "--profile", "fast-math"])
            self.assertEqual(error.exception.code, 2)
            self.assertFalse(output.exists())

    def test_cli_profile_receipt_matches_effective_command_without_claiming_speed(self):
        with tempfile.TemporaryDirectory() as temp:
            records = {}
            for profile, expected in (("baseline", "-O2"), ("optimized", "-O3")):
                output = Path(temp) / profile
                capture = io.StringIO()
                with contextlib.redirect_stdout(capture):
                    result = build.main(["--generated", str(Path(temp) / "missing"),
                                         "--output", str(output), "--cc", "/no/such/rv32-gcc",
                                         "--profile", profile, "--dry-run"])
                plan = json.loads(capture.getvalue())
                self.assertEqual(result, 0)
                self.assertEqual([arg for arg in plan["argv"] if arg.startswith("-O")], [expected])
                record = plan["build_profile"]
                self.assertEqual(record["name"], profile)
                self.assertEqual(record["optimization_flag"], expected)
                self.assertFalse(record["lto"])
                self.assertEqual(record["performance_status"], "NOT_MEASURED_BY_BUILD_TOOL")
                encoded = json.dumps(record["effective_flags"], separators=(",", ":")).encode()
                self.assertEqual(record["effective_flags_sha256"], hashlib.sha256(encoded).hexdigest())
                self.assertFalse(output.exists())
                records[profile] = record
            self.assertEqual(records["optimized"]["effective_flags"],
                             ["-O3" if flag == "-O2" else flag for flag in records["baseline"]["effective_flags"]])
            self.assertNotEqual(records["baseline"]["effective_flags_sha256"],
                                records["optimized"]["effective_flags_sha256"])

    def test_missing_inputs_dry_run_is_read_only(self):
        with tempfile.TemporaryDirectory() as temp:
            generated, output = Path(temp) / "missing assets", Path(temp) / "new output"
            capture = io.StringIO()
            with contextlib.redirect_stdout(capture):
                result = build.main(["--generated", str(generated), "--output", str(output),
                                     "--cc", "/no/such/rv32-gcc", "--dry-run"])
            plan = json.loads(capture.getvalue())
            self.assertEqual(result, 0)
            self.assertEqual(plan["status"], "PLAN_ONLY")
            self.assertFalse(plan["build_executed"])
            self.assertFalse(plan["programming_performed"])
            self.assertEqual(plan["build_profile"]["name"], "baseline")
            self.assertEqual(plan["build_profile"]["optimization_flag"], "-O2")
            self.assertEqual(len(plan["missing"]), 4)
            self.assertFalse(output.exists())
            self.assertFalse(generated.exists())

    def test_missing_assets_build_is_blocked_without_writing(self):
        with tempfile.TemporaryDirectory() as temp:
            output = Path(temp) / "no-build"
            capture = io.StringIO()
            with contextlib.redirect_stdout(capture):
                result = build.main(["--generated", str(Path(temp) / "missing"),
                                     "--output", str(output), "--cc", "/no/such/rv32-gcc",
                                     "--profile", "optimized", "--build"])
            record = json.loads(capture.getvalue())
            self.assertEqual(result, 2)
            self.assertEqual(record["status"], "BUILD_BLOCKED_MISSING_OR_INVALID_INPUTS")
            self.assertFalse(record["build_executed"])
            self.assertEqual(record["build_profile"]["name"], "optimized")
            self.assertFalse(output.exists())

    def test_asset_digest_and_model_binding_rejected_on_change(self):
        # Structural test fixtures, never supplied to a production compile.
        with tempfile.TemporaryDirectory() as temp:
            generated = Path(temp)
            blob = struct.pack("<3I", 0x31544b4e, 1, 128) + bytes(116)
            (generated / "tokenizer.nxt").write_bytes(blob)
            (generated / "full_weights.h").write_text("/* test fixture, not weights */\n")
            model = json.loads((ROOT / "docs/spec/model-pack-v1-manifest.json").read_text())["sha256"]
            identity = '#define T25_MODEL_SHA256 "%s"\n#define T25_TOKENIZER_SHA256 "%s"\n'
            (generated / "t25_identity.h").write_text(identity % (model, hashlib.sha256(blob).hexdigest()))
            self.assertFalse(build.asset_check(generated, ROOT)["errors"])
            (generated / "tokenizer.nxt").write_bytes(blob[:-1] + b"x")
            self.assertIn("tokenizer.nxt SHA256 differs", " ".join(build.asset_check(generated, ROOT)["errors"]))
            (generated / "t25_identity.h").write_text(identity % ("0" * 64, hashlib.sha256(blob[:-1] + b"x").hexdigest()))
            self.assertIn("candidate pinned model", " ".join(build.asset_check(generated, ROOT)["errors"]))

    def test_existing_output_never_overwritten_by_plan(self):
        with tempfile.TemporaryDirectory() as temp:
            out = Path(temp) / "already-built"
            out.mkdir()
            marker = out / "application.elf"
            marker.write_bytes(b"existing candidate")
            capture = io.StringIO()
            with contextlib.redirect_stdout(capture):
                result = build.main(["--generated", str(Path(temp) / "missing"),
                                     "--output", str(out), "--dry-run"])
            self.assertEqual(result, 0)
            self.assertIn("output already exists", " ".join(json.loads(capture.getvalue())["errors"]))
            self.assertEqual(marker.read_bytes(), b"existing candidate")

    def test_native_or_malformed_elf_is_not_production_evidence(self):
        with tempfile.TemporaryDirectory() as temp:
            elf = Path(temp) / "application.elf"
            for data in (b"not an ELF", b"\x7fELF\x02\x01\x01" + bytes(128)):
                elf.write_bytes(data)
                with self.assertRaises(ValueError):
                    build.inspect_application(elf, ROOT)


if __name__ == "__main__":
    unittest.main()
